-- RENTOURA.LK — MIGRATION 010: SYNC CANONICAL CATEGORY TAXONOMY
-- Synchronizes the entire website category taxonomy from the canonical frontend definitions.
-- Handles Level 1 (Main), Level 2 (Sub), and Level 3 (Third Level / Type) options across rental, job, and service modules.
-- Preserves existing UUIDs where matching, inserts new items, and sets unmatched legacy rows to status = 'inactive'.
-- Repeat-safe & idempotent.

BEGIN;

-- 1. TEMPORARY CANONICAL TAXONOMY STAGING TABLE
CREATE TEMP TABLE temp_canonical_categories (
  module listing_module NOT NULL,
  level integer NOT NULL,
  name text NOT NULL,
  slug text NOT NULL,
  parent_module listing_module,
  parent_slug text,
  parent_level integer,
  sort_order integer NOT NULL DEFAULT 0,
  icon_key text,
  description text
) ON COMMIT DROP;

-- 2. POPULATE STAGING DATA FROM CANONICAL FRONTEND TAXONOMY

-- 3. UPSERT LEVEL 1 MAIN CATEGORIES
SELECT 
  tc.module, 
  tc.name, 
  tc.slug, 
  NULL, 
  1, 
  'active', 
  tc.sort_order, 
  tc.icon_key, 
  tc.description
FROM temp_canonical_categories tc
WHERE tc.level = 1
ON CONFLICT (module, slug) WHERE parent_id IS NULL 
DO UPDATE SET 
  name = EXCLUDED.name,
  status = 'active',
  sort_order = EXCLUDED.sort_order,
  icon_key = EXCLUDED.icon_key,
  description = EXCLUDED.description,
  updated_at = now();

-- 4. UPSERT LEVEL 2 SUBCATEGORIES
SELECT 
  tc.module, 
  tc.name, 
  tc.slug, 
  p.id AS parent_id, 
  2, 
  'active', 
  tc.sort_order, 
  tc.icon_key, 
  tc.description
FROM temp_canonical_categories tc
JOIN public.categories p ON p.module = tc.parent_module AND p.slug = tc.parent_slug AND p.level = 1 AND p.parent_id IS NULL
WHERE tc.level = 2
ON CONFLICT (module, slug, parent_id) WHERE parent_id IS NOT NULL 
DO UPDATE SET 
  name = EXCLUDED.name,
  status = 'active',
  sort_order = EXCLUDED.sort_order,
  icon_key = EXCLUDED.icon_key,
  description = EXCLUDED.description,
  updated_at = now();

-- 5. UPSERT LEVEL 3 THIRD-LEVEL / TYPE OPTIONS
SELECT 
  tc.module, 
  tc.name, 
  tc.slug, 
  p.id AS parent_id, 
  3, 
  'active', 
  tc.sort_order, 
  tc.icon_key, 
  tc.description
FROM temp_canonical_categories tc
JOIN temp_canonical_categories t_parent ON tc.parent_slug = t_parent.slug AND tc.parent_level = t_parent.level AND tc.parent_module = t_parent.module
JOIN public.categories p_main ON t_parent.parent_module = p_main.module AND t_parent.parent_slug = p_main.slug AND p_main.level = 1 AND p_main.parent_id IS NULL
JOIN public.categories p ON p.module = tc.parent_module AND p.slug = tc.parent_slug AND p.parent_id = p_main.id AND p.level = 2
WHERE tc.level = 3
ON CONFLICT (module, slug, parent_id) WHERE parent_id IS NOT NULL 
DO UPDATE SET 
  name = EXCLUDED.name,
  status = 'active',
  sort_order = EXCLUDED.sort_order,
  icon_key = EXCLUDED.icon_key,
  description = EXCLUDED.description,
  updated_at = now();

-- 6. SET UNMATCHED LEGACY CATEGORIES TO INACTIVE (PRESERVE DATA, DISABLE UNMATCHED)
WITH active_canonical_ids AS (
  SELECT c.id
  FROM public.categories c
  JOIN temp_canonical_categories tc1 ON c.module = tc1.module AND c.slug = tc1.slug AND c.level = 1 AND tc1.level = 1 AND c.parent_id IS NULL
  UNION ALL
  SELECT c.id
  FROM public.categories c
  JOIN temp_canonical_categories tc2 ON c.module = tc2.module AND c.slug = tc2.slug AND c.level = 2 AND tc2.level = 2
  JOIN public.categories p ON c.parent_id = p.id AND p.slug = tc2.parent_slug AND p.level = 1
  UNION ALL
  SELECT c.id
  FROM public.categories c
  JOIN temp_canonical_categories tc3 ON c.module = tc3.module AND c.slug = tc3.slug AND c.level = 3 AND tc3.level = 3
  JOIN public.categories p ON c.parent_id = p.id AND p.slug = tc3.parent_slug AND p.level = 2
)
UPDATE public.categories
SET status = 'inactive', updated_at = now()
WHERE id NOT IN (SELECT id FROM active_canonical_ids);

COMMIT;
